/// <summary>
/// Logic block used to move multiple license plates at the same time
/// </summary>
class MwmsLogicBlockMoveMultipleLicensePlates extends MwmsLogicBlock implements TFMLogicBlockDataCollectionInterface
{
}

Method.Source:
public Set autoCreatedProcesses()
{
    Set ret = super();
    TFMProcess process = TFMProcess::Construct('MoveMultiLicensePlates');
    process.addBlock(this);
    ret.add(process);
    return ret;
}

/// <summary>
/// This method provides the header fields, that are needed to find out which data should be collected.
/// </summary>
/// <returns>A MobReferenceDataConfiguration object, containing registration collectors for the header.</returns>
public TFMReferenceDataConfiguration headerFieldsNeeded()
{
    TFMRegistrationCollectorList    warehouse = TFMGetReferenceData::createDefaultWarehouseReferenceData(10, strLwr(extendedTypeStr(InventLocationId)));
    refConf.addCollector(warehouse);

    return refConf;
}

/// <summary>
/// This method gives you the registration collectors for this data collection block.
/// </summary>
/// <returns>A collection of registration collectors.</returns>
public TFMRegistrationCollectors registrationCollectors()
{
    TFMRegistrationCollectors				returnCollectors = TFMRegistrationCollectors::Construct();
    TFMRegistrationCollectorTypeAndQuantity licensePlates = new TFMRegistrationCollectorTypeAndQuantity(1,extendedTypeStr(WHSLicensePlateId),"@WAX67","@WAX67","@WAX67");
    TFMRegistrationCollectorText			Location = TFMRegistrationCollector::collectorFromEDT(extendedTypeStr(WMSLocationId));
    Location.parmId(20);

    licensePlates.parmUniqueValues(true);
    licensePlates.setOnlineValidationDocument(methodStr(MobOnlineValidator, LicensePlateValidation));

    returnCollectors.addCollector(licensePlates);
    returnCollectors.addCollector(Location);

    return returnCollectors;
}

/// <summary>
/// This method is called before the post method, and gives the option to add extra registration collectors for the user to be prompted for before the post method is executed.
/// </summary>    
/// <returns>Returns a MobRegistrationCollectors object if the user must be further prompted, otherwise it returns null</returns>
public TFMRegistrationCollectors prePostRegistrationCollectors()
{
    return null;
}

/// <summary>
/// The method executed when all data has been collected, and contains the posting logic.
/// </summary>
/// <returns>A MobPostResponseData object.</returns>
public TFMPostResponseData post()
{
    TFMPostResponseData     postResponse    = TFMPostResponseData::Construct();
    TFMRequestItemAndDimensionElement  whsRequest      = request.convertToOtherRequestType(classStr(TFMRequestItemAndDimensionElement));
    str					lps		= request.getFieldValue(extendedTypeStr(WHSLicensePlateId));
    WMSLocationId		locId	= request.getFieldValue(extendedTypeStr(WMSLocationId));
    InventLocationId	whs		= whsRequest.parmWarehouse();
    ListEnumerator		lpList	= strSplit(lps,';').getEnumerator();
    WhsLicensePlateId	lpToMove;

    if (!WMSLocation::exist(locId,whs))
    {
        throw Error (strFmt("@SYS53781",locId,whs));
    }

    while(lpList.moveNext())
    {
        lpToMove = subStr(lpList.current(),1,strScan(lpList.current(),'=',1,100)-1);
        MobPostHelper::MoveLicensePlate(lpToMove,whs,locId);
    }

    return postResponse;
}
